import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { Icon, IconSizes, IconColors } from '../../components/common/IconTheme';
import axios from 'axios';

const UserStats = () => {
  const { user } = useAuth();
  const [stats, setStats] = useState({
    totalUsers: 0,
    activeUsers: 0,
    inactiveUsers: 0,
    roleDistribution: {
      admin: 0,
      tuteur: 0,
      apprenti: 0
    },
    monthlyRegistrations: [],
    userActivity: []
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (user?.role === 'admin') {
      fetchUserStats();
    }
  }, [user]);

  const fetchUserStats = async () => {
    try {
      setLoading(true);
      const response = await axios.get('/api/admin/user-stats', {
        headers: {
          Authorization: `Bearer ${localStorage.getItem('token')}`
        }
      });
      setStats(response.data);
    } catch (err) {
      setError('Erreur lors du chargement des statistiques');
      console.error('Erreur statistiques:', err);
    } finally {
      setLoading(false);
    }
  };

  if (user?.role !== 'admin') {
    return (
      <div className="main-content">
        <div className="container">
          <div className="card">
            <div className="card-header">
              <h2>Accès refusé</h2>
            </div>
            <div className="card-body">
              <p>Vous n'avez pas les permissions nécessaires pour accéder à cette page.</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="main-content">
        <div className="container">
          <div className="card">
            <div className="card-body text-center">
              <Icon name="loading" size={IconSizes.xl} className="spin" />
              <p>Chargement des statistiques...</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="main-content">
        <div className="container">
          <div className="card">
            <div className="card-body text-center">
              <Icon name="error" size={IconSizes.xl} color={IconColors.danger} />
              <p className="text-danger">{error}</p>
              <button onClick={fetchUserStats} className="btn">
                Réessayer
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="main-content">
      <div className="container">
        {/* En-tête */}
        <div className="card">
          <div className="card-header">
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
              <Icon name="barChart" size={IconSizes.md} color={IconColors.primary} />
              <h3 style={{ margin: 0, color: '#495057' }}>
                Statistiques des Utilisateurs
              </h3>
            </div>
          </div>
        </div>

        {/* Métriques principales */}
        <div className="stats-grid" style={{ marginTop: '1.5rem' }}>
          <div className="stat-card">
            <div className="stat-icon" style={{ background: 'var(--primary-blue)' }}>
              <Icon name="user" size={IconSizes.lg} color={IconColors.white} />
            </div>
            <div className="stat-content">
              <div className="stat-number">{stats.totalUsers}</div>
              <div className="stat-label">Total Utilisateurs</div>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon" style={{ background: 'var(--success)' }}>
              <Icon name="checkCircle" size={IconSizes.lg} color={IconColors.white} />
            </div>
            <div className="stat-content">
              <div className="stat-number">{stats.activeUsers}</div>
              <div className="stat-label">Utilisateurs Actifs</div>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon" style={{ background: 'var(--warning)' }}>
              <Icon name="pause" size={IconSizes.lg} color={IconColors.white} />
            </div>
            <div className="stat-content">
              <div className="stat-number">{stats.inactiveUsers}</div>
              <div className="stat-label">Utilisateurs Inactifs</div>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon" style={{ background: 'var(--info)' }}>
              <Icon name="graduation" size={IconSizes.lg} color={IconColors.white} />
            </div>
            <div className="stat-content">
              <div className="stat-number">{stats.roleDistribution.tuteur}</div>
              <div className="stat-label">Tuteurs</div>
            </div>
          </div>
        </div>

        {/* Distribution des rôles */}
        <div className="card" style={{ marginTop: '1.5rem' }}>
          <div className="card-header">
            <h4>Distribution des Rôles</h4>
          </div>
          <div className="card-body">
            <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
              <div style={{ 
                display: 'flex', 
                alignItems: 'center', 
                gap: '0.5rem',
                padding: '0.75rem',
                backgroundColor: 'var(--danger)',
                color: 'white',
                borderRadius: '8px',
                minWidth: '120px'
              }}>
                <Icon name="admin" size={IconSizes.sm} color={IconColors.white} />
                <span>Admin: {stats.roleDistribution.admin}</span>
              </div>
              
              <div style={{ 
                display: 'flex', 
                alignItems: 'center', 
                gap: '0.5rem',
                padding: '0.75rem',
                backgroundColor: 'var(--success)',
                color: 'white',
                borderRadius: '8px',
                minWidth: '120px'
              }}>
                <Icon name="graduation" size={IconSizes.sm} color={IconColors.white} />
                <span>Tuteur: {stats.roleDistribution.tuteur}</span>
              </div>
              
              <div style={{ 
                display: 'flex', 
                alignItems: 'center', 
                gap: '0.5rem',
                padding: '0.75rem',
                backgroundColor: 'var(--primary-blue)',
                color: 'white',
                borderRadius: '8px',
                minWidth: '120px'
              }}>
                <Icon name="user" size={IconSizes.sm} color={IconColors.white} />
                <span>Apprenti: {stats.roleDistribution.apprenti}</span>
              </div>
            </div>
          </div>
        </div>

        {/* Graphique des inscriptions mensuelles */}
        <div className="card" style={{ marginTop: '1.5rem' }}>
          <div className="card-header">
            <h4>Inscriptions Mensuelles</h4>
          </div>
          <div className="card-body">
            <div style={{ 
              display: 'flex', 
              alignItems: 'end', 
              gap: '0.5rem', 
              height: '200px',
              padding: '1rem 0'
            }}>
              {stats.monthlyRegistrations.map((month, index) => (
                <div key={index} style={{ 
                  display: 'flex', 
                  flexDirection: 'column', 
                  alignItems: 'center',
                  gap: '0.25rem'
                }}>
                  <div style={{
                    width: '40px',
                    height: `${(month.count / Math.max(...stats.monthlyRegistrations.map(m => m.count))) * 150}px`,
                    backgroundColor: 'var(--primary-blue)',
                    borderRadius: '4px 4px 0 0',
                    minHeight: '4px'
                  }} />
                  <span style={{ 
                    fontSize: '0.75rem', 
                    color: '#6c757d',
                    writingMode: 'vertical-rl',
                    textOrientation: 'mixed'
                  }}>
                    {month.month}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Actions rapides */}
        <div className="card" style={{ marginTop: '1.5rem' }}>
          <div className="card-header">
            <h4>Actions Rapides</h4>
          </div>
          <div className="card-body">
            <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
              <button 
                onClick={() => window.location.href = '/admin'}
                className="btn"
                style={{ backgroundColor: 'var(--primary-blue)', color: 'white' }}
              >
                <Icon name="admin" size={IconSizes.sm} color={IconColors.white} />
                Gérer les Utilisateurs
              </button>
              
              <button 
                onClick={fetchUserStats}
                className="btn btn-outline"
              >
                <Icon name="refresh" size={IconSizes.sm} />
                Actualiser les Stats
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default UserStats;
